61:.radar-brand-title { font-family: var(--radar-mono); font-size: 13px; font-weight: 600; letter-spacing: 3px; color: var(--radar-muted); white-space: nowrap; }
66:.radar-feed-pill { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 999px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1px; white-space: nowrap; }
71:.radar-clock-time { font-size: 8px; font-weight: 600; }
73:.radar-clock-label { font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
74:.radar-head-button { min-height: 36px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
77:.radar-modes .radar-mode { min-height: 36px; padding: 6px 14px; border: 0; border-radius: 0; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; line-height: 1.25; cursor: pointer; }
81:.radar-days { display: flex; align-items: center; gap: 6px; font-family: var(--radar-mono); font-size: 13px; letter-spacing: 1px; }
85:.radar-day-live { min-height: 36px; padding: 6px 12px; border: 1px solid var(--radar-accent); border-radius: 8px; background: rgba(59, 130, 246, 0.14); color: var(--radar-ink); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
87:.radar-tenant { padding-left: 16px; border-left: 1px solid var(--radar-line); font-size: 13px; font-weight: 600; letter-spacing: 1px; color: var(--radar-muted); }
98:.radar-eyebrow { display: block; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 3px; color: var(--radar-dim); }
99:.radar-feed-head h1 { margin: 4px 0 0; font-size: 24px; font-weight: 600; letter-spacing: 1px; }
100:.radar-shown { font-family: var(--radar-mono); font-size: 12px; color: var(--radar-dim); text-align: right; }
101:.radar-x { flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; padding: 0; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 50%; background: transparent; color: var(--radar-muted); font-size: 17px; line-height: 1; cursor: pointer; }
108:.radar-no-match { margin: 16px 0; font-size: 13px; color: var(--radar-muted); }
109:.radar-link { padding: 0; border: 0; background: none; color: var(--radar-accent); font-size: inherit; text-decoration: underline; cursor: pointer; }
116:.radar-kpi-value { font-size: 26px; font-weight: 600; line-height: 1; font-variant-numeric: tabular-nums; }
117:.radar-kpi-label { min-height: 2.6em; font-family: var(--radar-mono); font-size: 11px; line-height: 1.35; letter-spacing: 1px; color: var(--radar-muted); }
127:.radar-chip { min-height: 32px; text-align: center; padding: 7px 14px; border-radius: 8px; border: 1px solid rgba(59, 130, 246, 0.22); background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 11px; font-weight: 600; letter-spacing: 1px; line-height: 1.25; white-space: nowrap; cursor: pointer; }
134:.radar-locked-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 2px; color: var(--radar-dim); }
137:.radar-locked-title { font-size: 21px; font-weight: 600; line-height: 1.2; }
138:.radar-locked-kind { font-size: 14px; font-weight: 400; line-height: 1.4; color: var(--radar-muted); }
140:.radar-locked-fact-label { display: block; margin-bottom: 2px; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 0.8px; color: var(--radar-dim); }
141:.radar-locked-fact-value { font-size: 15px; }
142:.radar-locked-detail { font-size: 14px; line-height: 1.4; color: var(--radar-muted); }
144:.radar-primary { min-height: 44px; padding: 10px 16px; border: 1px solid var(--radar-accent); border-radius: 8px; background: var(--radar-accent); color: #ffffff; font-size: 13px; font-weight: 700; letter-spacing: 1.5px; cursor: pointer; }
145:.radar-secondary { display: inline-flex; align-items: center; min-height: 44px; box-sizing: border-box; padding: 10px 16px; border: 1px solid rgba(59, 130, 246, 0.45); border-radius: 8px; color: var(--radar-ink); font-size: 13px; font-weight: 600; letter-spacing: 1.5px; text-decoration: none; }
152:.radar-stale { margin: 0; padding: 8px 12px; border-radius: 8px; border: 1px solid var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); font-size: 13px; }
154:.radar-ack-error { color: var(--radar-amber-ink); font-size: 12px; }
172:.radar-row-age { font-size: 14px; font-weight: 600; color: var(--radar-ink); }
173:.radar-row-clock { font-size: 11px; color: var(--radar-dim); }
175:.radar-row-title { font-size: 8px; font-weight: 600; color: var(--radar-ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
176:.radar-row-detail { font-size: 12px; color: var(--radar-detail); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
178:.radar-tag { min-width: 62px; box-sizing: border-box; padding: 3px 6px; border-radius: 4px; font-family: var(--radar-mono); font-size: 10px; font-weight: 600; letter-spacing: 1.5px; text-align: center; white-space: nowrap; }
183:.radar-pill { padding: 3px 7px; border-radius: 4px; font-family: var(--radar-mono); font-size: 10px; font-weight: 600; letter-spacing: 1.5px; white-space: nowrap; }
196:.radar-toolbar { --radar-heading-h: 38px; display: flex; align-items: center; gap: 14px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1.5px; color: var(--radar-dim); }
202:.radar-toolbar-title { font-family: var(--radar-display); font-size: 15px; font-weight: 600; letter-spacing: 3px; color: var(--radar-ink); }
206:.radar-toolbar button { min-height: 40px; padding: 8px 14px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
248:.radar-axis { position: absolute; transform: translate(-50%, -50%); padding: 0.35em 0.7em; border-radius: 6px; border: 1px solid transparent; background: var(--radar-axis-bg); color: var(--radar-dim); font-family: var(--radar-display); font-size: clamp(9px, 1.55cqi, 12px); font-weight: 600; letter-spacing: 0.12em; line-height: 1.2; text-transform: uppercase; text-align: center; white-space: nowrap; cursor: pointer; }
252:.radar-axis-count { display: block; margin-top: 2px; font-family: var(--radar-mono); font-size: 0.85em; font-weight: 500; letter-spacing: 0.08em; color: var(--radar-faint); }
258:.radar-arrivals-title { font-family: var(--radar-mono); font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
263:.radar-arrivals-axis { display: flex; justify-content: flex-end; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 1.5px; color: var(--radar-faint); }
264:.radar-telemetry-read { padding-top: 8px; border-top: 1px solid rgba(59, 130, 246, 0.08); font-family: var(--radar-mono); font-size: 10.5px; letter-spacing: 1.5px; color: var(--radar-faint); }
.radar-brand-blip { fill: var(--radar-amber); }
.radar-feed-pill { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 999px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1px; white-space: nowrap; }
.radar-feed-pill--stale { border-color: var(--radar-amber); color: var(--radar-stale-ink); }
.radar-feed-pill--stale .radar-live-dot { background: var(--radar-amber); box-shadow: 0 0 10px var(--radar-amber); }
.radar-live-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--radar-accent); box-shadow: 0 0 10px var(--radar-accent); animation: radar-livedot 1.2s infinite; }
.radar-clock { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.1; font-family: var(--radar-mono); }
.radar-clock-time { font-size: 8px; font-weight: 600; }
.radar-clock--utc .radar-clock-time { color: var(--radar-dim); }
.radar-clock-label { font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-head-button { min-height: 36px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-screen:fullscreen .radar-head-button { display: none; }
.radar-row--resolved { opacity: 0.62; }
.radar-row-when { display: flex; flex-direction: column; gap: 2px; font-family: var(--radar-mono); }
.radar-row-age { font-size: 14px; font-weight: 600; color: var(--radar-ink); }
.radar-row-clock { font-size: 11px; color: var(--radar-dim); }
.radar-row-text { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.radar-row-title { font-size: 8px; font-weight: 600; color: var(--radar-ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.radar-row-detail { font-size: 12px; color: var(--radar-detail); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.radar-tag { min-width: 62px; box-sizing: border-box; padding: 3px 6px; border-radius: 4px; font-family: var(--radar-mono); font-size: 10px; font-weight: 600; letter-spacing: 1.5px; text-align: center; white-space: nowrap; }
